#
# TABLE STRUCTURE FOR: Articulos
#

DROP TABLE IF EXISTS `Articulos`;

CREATE TABLE `Articulos` (
  `sku` int(11) NOT NULL AUTO_INCREMENT,
  `Descripcion` text DEFAULT NULL,
  `Familia` varchar(50) DEFAULT NULL,
  `SubFamilia` varchar(50) DEFAULT NULL,
  `PesoBase` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`sku`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: Clientes
#

DROP TABLE IF EXISTS `Clientes`;

CREATE TABLE `Clientes` (
  `Cliente` int(11) NOT NULL AUTO_INCREMENT,
  `Nombre` varchar(100) DEFAULT NULL,
  `Direccion` text DEFAULT NULL,
  `FechaAlta` date DEFAULT NULL,
  `Estatus` varchar(50) DEFAULT NULL,
  `Credito` decimal(10,2) DEFAULT NULL,
  `Dias_Cred` int(11) DEFAULT NULL,
  `Nacional` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`Cliente`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: Facturas
#

DROP TABLE IF EXISTS `Facturas`;

CREATE TABLE `Facturas` (
  `Factura_id` int(11) NOT NULL AUTO_INCREMENT,
  `OrdendeVenta` int(11) DEFAULT NULL,
  `Cliente` int(11) DEFAULT NULL,
  `Vendedor` varchar(100) DEFAULT NULL,
  `sku` int(11) DEFAULT NULL,
  `NumeroDeLote` int(11) DEFAULT NULL,
  `Fecha_de_Orden` date DEFAULT NULL,
  `Fecha_de_Entrega` date DEFAULT NULL,
  `Venta_de_Inventario` tinyint(1) DEFAULT NULL,
  `Calidad` varchar(50) DEFAULT NULL,
  `Numero_de_Remision` int(11) DEFAULT NULL,
  `ToneladasOrdenadas` decimal(10,2) DEFAULT NULL,
  `ToneladasEntregadas` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`Factura_id`),
  KEY `OrdendeVenta` (`OrdendeVenta`),
  KEY `Cliente` (`Cliente`),
  KEY `sku` (`sku`),
  CONSTRAINT `Facturas_ibfk_1` FOREIGN KEY (`OrdendeVenta`) REFERENCES `Ordenes` (`OrdendeVenta`),
  CONSTRAINT `Facturas_ibfk_2` FOREIGN KEY (`Cliente`) REFERENCES `Clientes` (`Cliente`),
  CONSTRAINT `Facturas_ibfk_3` FOREIGN KEY (`sku`) REFERENCES `Articulos` (`sku`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: Ordenes
#

DROP TABLE IF EXISTS `Ordenes`;

CREATE TABLE `Ordenes` (
  `OrdendeVenta` int(11) NOT NULL AUTO_INCREMENT,
  `Cliente` int(11) DEFAULT NULL,
  `sku` int(11) DEFAULT NULL,
  `Toneladas_Requeridas` decimal(10,2) DEFAULT NULL,
  `Maquina` varchar(50) DEFAULT NULL,
  `Ancho` decimal(10,2) DEFAULT NULL,
  `Largo` decimal(10,2) DEFAULT NULL,
  `Fecha_de_Alta` date DEFAULT NULL,
  `Fecha_de_Embarque_Requerida` date DEFAULT NULL,
  `Fecha_de_Produccion_Requerida` date DEFAULT NULL,
  `Venta_de_Inventario` date DEFAULT NULL,
  PRIMARY KEY (`OrdendeVenta`),
  KEY `Cliente` (`Cliente`),
  KEY `sku` (`sku`),
  CONSTRAINT `Ordenes_ibfk_1` FOREIGN KEY (`Cliente`) REFERENCES `Clientes` (`Cliente`),
  CONSTRAINT `Ordenes_ibfk_2` FOREIGN KEY (`sku`) REFERENCES `Articulos` (`sku`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: Produccion
#

DROP TABLE IF EXISTS `Produccion`;

CREATE TABLE `Produccion` (
  `Job` int(11) NOT NULL AUTO_INCREMENT,
  `OrdendeVenta` int(11) DEFAULT NULL,
  `NumeroDeLote` int(11) DEFAULT NULL,
  `Cliente` int(11) DEFAULT NULL,
  `sku` int(11) DEFAULT NULL,
  `Vendedor` varchar(100) DEFAULT NULL,
  `ToneladasRequeridas` decimal(10,2) DEFAULT NULL,
  `ToneladasFabricadas` decimal(10,2) DEFAULT NULL,
  `Maquina` varchar(50) DEFAULT NULL,
  `Ancho` decimal(10,2) DEFAULT NULL,
  `Largo` decimal(10,2) DEFAULT NULL,
  `FechaDeProduccion` date DEFAULT NULL,
  PRIMARY KEY (`Job`),
  KEY `OrdendeVenta` (`OrdendeVenta`),
  KEY `Cliente` (`Cliente`),
  KEY `sku` (`sku`),
  CONSTRAINT `Produccion_ibfk_1` FOREIGN KEY (`OrdendeVenta`) REFERENCES `Ordenes` (`OrdendeVenta`),
  CONSTRAINT `Produccion_ibfk_2` FOREIGN KEY (`Cliente`) REFERENCES `Clientes` (`Cliente`),
  CONSTRAINT `Produccion_ibfk_3` FOREIGN KEY (`sku`) REFERENCES `Articulos` (`sku`)
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



